var data={cover:{homePg:"imgs/data/110164051.jpg",effectPg:"imgs/data/110164053.jpg",preface:"他们热爱这个比我们更热的夏天，<br/>只为真实故事里的那一份坚持。",bgMusic:"imgs/data/ceshiyingyue2.mp3"},pages:[{bgUrl:"imgs/data/110164062.jpg",imageUrl:"imgs/data/110164159.jpg",imageOsrc:"imgs/data/110164159.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"8:21",outLine:"青岛城阳区青峰社区，一名在工地打桩的妇女将坑井下的泥土摇了上来。她的丈夫此时正在井底挖土，不到一岁的孩子坐在童车上四处张望。",mainWords:"青岛城阳区青峰社区，一名在工地打桩的妇女将坑井下的泥土摇了上来。她的丈夫此时正在井底挖土，不到一岁的孩子坐在童车上四处张望。"},{bgUrl:"imgs/data/110164063.jpg",imageUrl:"imgs/data/110164160.jpg",imageOsrc:"imgs/data/110164160.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"8:48",outLine:"在这个工地打井的，有很多对夫妻，一对夫妻负责一个桩基。男人下井挖土，女人负责将土拉上去。",mainWords:"在这个工地打井的，有很多对夫妻，一对夫妻负责一个桩基。男人下井挖土，女人负责将土拉上去。"},{bgUrl:"imgs/data/110197316.jpg",imageUrl:"imgs/data/110196104.jpg",imageOsrc:"imgs/data/110196104.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"8:55",outLine:"往外运土是力气活，而且得非常小心。满满一桶泥土正好悬吊在井下人的头顶，倘若手不小心松了，就会伤及自己的男人。",mainWords:"往外运土是力气活，而且得非常小心。满满一桶泥土正好悬吊在井下人的头顶，倘若手不小心松了，就会伤及自己的男人。"},{bgUrl:"imgs/data/110197334.jpg",imageUrl:"imgs/data/110196152.jpg",imageOsrc:"imgs/data/110196152.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"9:10",outLine:"大多数夫妻都是用手摇工具从井下运土，条件好一些的，会用电动机器。",mainWords:"大多数夫妻都是用手摇工具从井下运土，条件好一些的，会用电动机器。"},{bgUrl:"imgs/data/110197346.jpg",imageUrl:"imgs/data/110196189.jpg",imageOsrc:"imgs/data/110196189.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"9:39",outLine:"青峰社区正在进行“新农村”改造，这些外来的夫妻们承揽了新建房屋的打桩工作。他们大多来自四川、河南、山东菏泽等地。",mainWords:"青峰社区正在进行“新农村”改造，这些外来的夫妻们承揽了新建房屋的打桩工作。他们大多来自四川、河南、山东菏泽等地。"},{bgUrl:"imgs/data/110197405.jpg",imageUrl:"imgs/data/110196338.jpg",imageOsrc:"imgs/data/110196338.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"9:55",outLine:"一对夫妻一天要完成一个桩的进度，大部分时间是无法照顾孩子的。这个孩子困了，在工地边上睡着了。",mainWords:"一对夫妻一天要完成一个桩的进度，大部分时间是无法照顾孩子的。这个孩子困了，在工地边上睡着了。"},{bgUrl:"imgs/data/110197425.jpg",imageUrl:"imgs/data/110196312.jpg",imageOsrc:"imgs/data/110196312.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"10:17",outLine:"往深处打桩前，需要先用竹子把井壁绷住，防止泥土崩塌，造成事故。",mainWords:"往深处打桩前，需要先用竹子把井壁绷住，防止泥土崩塌，造成事故。"},{bgUrl:"imgs/data/110197445.jpg",imageUrl:"imgs/data/110196300.jpg",imageOsrc:"imgs/data/110196300.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"10:52",outLine:"打桩的工人们包揽所有的工作，竹条的制作、钢筋的焊接也都得他们自己来。",mainWords:"打桩的工人们包揽所有的工作，竹条的制作、钢筋的焊接也都得他们自己来。"},{bgUrl:"imgs/data/110197548.jpg",imageUrl:"imgs/data/110196222.jpg",imageOsrc:"imgs/data/110196222.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"11:08",outLine:"一对夫妻在焊接钢筋，他们的孩子在边上玩耍。夫妻俩时刻确保孩子呆在视线范围内，因为工地上很危险。",mainWords:"一对夫妻在焊接钢筋，他们的孩子在边上玩耍。夫妻俩时刻确保孩子呆在视线范围内，因为工地上很危险。"},{bgUrl:"imgs/data/110197635.jpg",imageUrl:"imgs/data/110196360.jpg",imageOsrc:"imgs/data/110196360.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"11:22",outLine:"井洞打到5米以上深度时，井下人的身影会渐渐变得难以辨认，夫妻俩需要默契地配合。",mainWords:"井洞打到5米以上深度时，井下人的身影会渐渐变得难以辨认，夫妻俩需要默契地配合。"},{bgUrl:"imgs/data/110197656.jpg",imageUrl:"imgs/data/110196383.jpg",imageOsrc:"imgs/data/110196383.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"11:41",outLine:"打桩工们上头有个老板，老板负责找生意，然后派活。夫妻俩干一个月能赚到6000—9000元的工钱。",mainWords:"打桩工们上头有个老板，老板负责找生意，然后派活。夫妻俩干一个月能赚到6000—9000元的工钱。"},{bgUrl:"imgs/data/110164094.jpg",imageUrl:"imgs/data/110164179.jpg",imageOsrc:"imgs/data/110164179.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"14:05",outLine:"一名刚从井下上来的工人，身上满是泥浆。井下十分潮闷。",mainWords:"一名刚从井下上来的工人，身上满是泥浆。井下十分潮闷。"},{bgUrl:"imgs/data/110164099.jpg",imageUrl:"imgs/data/110164180.jpg",imageOsrc:"imgs/data/110164180.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"14:39",outLine:"一名工人拖着疲惫的身躯从井下上到地面，坐下抽烟休息。",mainWords:"一名工人拖着疲惫的身躯从井下上到地面，坐下抽烟休息。"},{bgUrl:"imgs/data/110164100.jpg",imageUrl:"imgs/data/110164181.jpg",imageOsrc:"imgs/data/110164181.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"15:53",outLine:"皮外伤很常见。他们一般会在伤口抹红药水消炎。",mainWords:"皮外伤很常见。他们一般会在伤口抹红药水消炎。"},{bgUrl:"imgs/data/110164101.jpg",imageUrl:"imgs/data/110164182.jpg",imageOsrc:"imgs/data/110164182.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"16:12",outLine:"两个年轻工人坐在井口休息，用沾满黄泥的衣服在脸上擦汗。",mainWords:"两个年轻工人坐在井口休息，用沾满黄泥的衣服在脸上擦汗。"},{bgUrl:"imgs/data/110164102.jpg",imageUrl:"imgs/data/110164183.jpg",imageOsrc:"imgs/data/110164183.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"17:34",outLine:"夏天工棚闷热，蚊子又多，得支上蚊帐。",mainWords:"夏天工棚闷热，蚊子又多，得支上蚊帐。"},{bgUrl:"imgs/data/110164104.jpg",imageUrl:"imgs/data/110164185.jpg",imageOsrc:"imgs/data/110164185.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"6:37",outLine:"清晨，一名工人在户外洗漱。工地里没有浴室。",mainWords:"清晨，一名工人在户外洗漱。工地里没有浴室。"},{bgUrl:"imgs/data/110164105.jpg",imageUrl:"imgs/data/110164191.jpg",imageOsrc:"imgs/data/110164191.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"17:06",outLine:"收工后，男人们就在露天场地洗澡。",mainWords:"收工后，男人们就在露天场地洗澡。"},{bgUrl:"imgs/data/110164107.jpg",imageUrl:"imgs/data/110164196.jpg",imageOsrc:"imgs/data/110164196.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"17:17",outLine:"他们一直住在临时工棚里，所有家当都在户外。",mainWords:"他们一直住在临时工棚里，所有家当都在户外。"},{bgUrl:"imgs/data/110164109.jpg",imageUrl:"imgs/data/110164226.jpg",imageOsrc:"imgs/data/110164226.jpg",imgVoice:"imgs/data/bgm_hot.mp3",timeClock:"17:46",outLine:"在一个工地，他们少则干十几天，多则干两个月，然后奔向下一个工地。",mainWords:"在一个工地，他们少则干十几天，多则干两个月，然后奔向下一个工地。"}],backCover:{backBg:"imgs/data/110164109.jpg",archives:[{phaseNum:"第001期",arcImg:"imgs/data/109129051.jpg",arcWords:"三轮车夫老颜：为儿再骑十年车",arcLink:"https://qd.sina.com.cn/zt2014/warm/index.html"},{phaseNum:"第002期",arcImg:"imgs/data/110164260.jpg",arcWords:"一个把癌症丈夫扛在肩上的女人",arcLink:"https://qd.sina.com.cn/zt2014/reai2/index.html"},{phaseNum:"第003期",arcImg:"imgs/data/110164261.jpg",arcWords:"“8090”硬汉：赴汤蹈火斗马蜂",arcLink:"https://qd.sina.com.cn/zt2014/xiaofanglove/index.html"},{phaseNum:"第004期",arcImg:"imgs/data/110164262.jpg",arcWords:"父子情深：在海上201米谋生",arcLink:"https://qd.sina.com.cn/zt2014/reaino4/index.html"},{phaseNum:"第005期",arcImg:"imgs/data/110164266.jpg",arcWords:"冰与火：光膀子的飞人",arcLink:"https://qd.sina.com.cn/zt2014/reaino5/index.html"}]}};